    "self-hosting.data.point1_title": "Single-process delivery",
    "self-hosting.data.point2_body": "PocketBase/SQLite is embedded; the data directory and backups are operator-owned, and permission checks run server-side.",
    "self-hosting.data.point2_title": "Data stays in your environment",
    "self-hosting.data.point3_body": "Backups, recovery drills and upgrades are up to the deployer; the database does not roll back automatically.",
